#pragma once
// Packed IPv6 forwarding image engine, protocol 3.
// Full-width (128 bit) interval compiler, byte-exact image builder,
// real-image scalar lookup kernel and cache-budgeted layout planner.
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

using Key = unsigned __int128;
using i128 = __int128;

static const int IMG_WIDTH[3] = {16, 8, 4};
static const int IMG_LANES[3] = {4, 8, 16};

inline std::string hexkey(Key x) {
    static const char* d = "0123456789abcdef";
    std::string s(32, '0');
    for (int i = 31; i >= 0; --i) { s[i] = d[(unsigned)(x & 15)]; x >>= 4; }
    return s;
}
inline Key key(const std::string& s) {
    if (s.size() != 32) throw std::runtime_error("key width");
    Key v = 0;
    for (char c : s) {
        int n = (c >= '0' && c <= '9') ? c - '0'
              : (c >= 'a' && c <= 'f') ? c - 'a' + 10
              : (c >= 'A' && c <= 'F') ? c - 'A' + 10 : -1;
        if (n < 0) throw std::runtime_error("key digit");
        v = (v << 4) | (unsigned)n;
    }
    return v;
}

// ---------------------------------------------------------------- byte helpers
inline void wr8(std::string& s, size_t at, unsigned v) { s[at] = (char)(v & 255); }
inline void wr16(std::string& s, size_t at, unsigned v) {
    s[at] = (char)(v & 255); s[at + 1] = (char)((v >> 8) & 255);
}
inline void wr32(std::string& s, size_t at, unsigned long long v) {
    for (int i = 0; i < 4; ++i) s[at + i] = (char)((v >> (8 * i)) & 255);
}
inline void wr128(std::string& s, size_t at, Key v) {
    for (int i = 0; i < 16; ++i) s[at + i] = (char)((unsigned)(v >> (8 * i)) & 255);
}
inline unsigned rd8(const std::string& s, size_t at) { return (unsigned char)s[at]; }
inline unsigned rd16(const std::string& s, size_t at) {
    return (unsigned)(unsigned char)s[at] | ((unsigned)(unsigned char)s[at + 1] << 8);
}
inline unsigned long long rd32(const std::string& s, size_t at) {
    unsigned long long v = 0;
    for (int i = 3; i >= 0; --i) v = (v << 8) | (unsigned)(unsigned char)s[at + i];
    return v;
}
inline Key rd128(const std::string& s, size_t at) {
    Key v = 0;
    for (int i = 15; i >= 0; --i) v = (v << 8) | (unsigned)(unsigned char)s[at + i];
    return v;
}

// ---------------------------------------------------------------- ATLAS
struct Entry { Key prefix; int length; long long next_hop; };
struct Run { Key start; long long hop; };

inline Entry make_entry(const std::string& s, int length, long long hop) {
    if (length < 0 || length > 128) throw std::runtime_error("route length");
    Entry e; e.prefix = key(s); e.length = length; e.next_hop = hop;
    Key size = (length == 0) ? (Key)0 : (((Key)1) << (128 - length));
    if (size) e.prefix = e.prefix / size * size;   // mask host bits
    return e;
}

// Maximal forwarding runs of one RIB version. Null next hop is -1.
inline std::vector<Run> atlas_runs(const std::vector<Entry>& fib) {
    struct Ev { std::vector<std::pair<int, long long> > rem, add; };
    std::map<Key, Ev> ev;
    ev[(Key)0];
    for (size_t i = 0; i < fib.size(); ++i) {
        const Entry& e = fib[i];
        ev[e.prefix].add.push_back(std::make_pair(e.length, e.next_hop));
        if (e.length > 0) {
            Key end = e.prefix + (((Key)1) << (128 - e.length));
            if (end != (Key)0) ev[end].rem.push_back(std::make_pair(e.length, e.next_hop));
        }
    }
    std::map<int, long long> active;
    std::vector<Run> out;
    for (std::map<Key, Ev>::iterator it = ev.begin(); it != ev.end(); ++it) {
        for (size_t j = 0; j < it->second.rem.size(); ++j) active.erase(it->second.rem[j].first);
        for (size_t j = 0; j < it->second.add.size(); ++j) active[it->second.add[j].first] = it->second.add[j].second;
        long long val = active.empty() ? -1 : active.rbegin()->second;
        if (out.empty() || out.back().hop != val) { Run r; r.start = it->first; r.hop = val; out.push_back(r); }
    }
    return out;
}

// ---------------------------------------------------------------- layout/image
struct Layout { int lo, span, mode, cached; std::vector<int> children; };
struct Answer { long long hop; int run; std::vector<unsigned long long> path; };
struct PackedResult { std::string image; std::vector<Answer> answers; };

inline unsigned layout_used(const Layout& n) {
    unsigned b = (unsigned)n.children.size();
    unsigned k = b ? b - 1 : (unsigned)n.span;
    return 32u + 4u * b + k * (unsigned)IMG_WIDTH[n.mode];
}
inline unsigned layout_pages(const Layout& n) { return (layout_used(n) + 63u) / 64u; }

inline std::string build_image(const std::vector<Key>& starts,
                               const std::vector<long long>& hops,
                               const std::vector<Layout>& nodes) {
    size_t R = starts.size();
    if (R == 0 || R > 64) throw std::runtime_error("run count");
    if (nodes.empty() || nodes.size() > 2 * R - 1) throw std::runtime_error("node count");
    std::vector<unsigned long long> off(nodes.size()), size(nodes.size());
    unsigned long long pos = 64;
    for (size_t i = 0; i < nodes.size(); ++i) {
        const Layout& n = nodes[i];
        if (n.mode < 0 || n.mode > 2) throw std::runtime_error("mode");
        size_t b = n.children.size();
        if (b > 9) throw std::runtime_error("fanout");
        if (b == 0 && (n.span < 1 || n.span > 8)) throw std::runtime_error("leaf span");
        if (b >= 2 && b > (size_t)n.span) throw std::runtime_error("fanout span");
        if (n.lo < 0 || n.lo + n.span > (int)R) throw std::runtime_error("range");
        Key spread = starts[n.lo + n.span - 1] - starts[n.lo];
        if (n.mode == 1 && !(spread < (((Key)1) << 64))) throw std::runtime_error("mode1 range");
        if (n.mode == 2 && !(spread < (((Key)1) << 32))) throw std::runtime_error("mode2 range");
        if (b >= 1 && b < 2) throw std::runtime_error("child count");
        size[i] = (unsigned long long)layout_pages(n) * 64ull;
        off[i] = pos;
        pos += size[i];
    }
    unsigned long long hopoff = pos;
    unsigned long long total = hopoff + ((4ull * R + 63ull) / 64ull) * 64ull;
    std::string img((size_t)total, '\0');
    memcpy(&img[0], "FIDX", 4);
    wr8(img, 4, 2);
    wr32(img, 8, (unsigned long long)R);
    wr32(img, 12, (unsigned long long)nodes.size());
    wr32(img, 16, hopoff);
    wr32(img, 20, total);
    for (size_t i = 0; i < nodes.size(); ++i) {
        const Layout& n = nodes[i];
        size_t b = n.children.size();
        unsigned long long o = off[i];
        wr8(img, o + 0, b ? 0u : 1u);
        wr8(img, o + 1, (unsigned)n.mode);
        wr8(img, o + 2, (unsigned)n.cached);
        wr8(img, o + 3, 0);
        wr16(img, o + 4, (unsigned)n.lo);
        wr16(img, o + 6, (unsigned)n.span);
        wr16(img, o + 8, b ? (unsigned)b : (unsigned)n.span);
        wr16(img, o + 10, 0);
        wr32(img, o + 12, size[i]);
        wr128(img, o + 16, starts[n.lo]);
        unsigned long long at = o + 32;
        std::vector<Key> keys;
        for (size_t c = 0; c < b; ++c) {
            int cid = n.children[c];
            if (cid < 0 || cid >= (int)nodes.size()) throw std::runtime_error("child id");
            wr32(img, at, off[cid]);
            at += 4;
        }
        Key base = starts[n.lo];
        if (b) {
            for (size_t c = 1; c < b; ++c) keys.push_back(starts[nodes[n.children[c]].lo]);
        } else {
            for (int t = 0; t < n.span; ++t) keys.push_back(starts[n.lo + t]);
        }
        for (size_t k = 0; k < keys.size(); ++k) {
            Key v = keys[k] - base;
            if (n.mode == 1 && !(v < (((Key)1) << 64))) throw std::runtime_error("key width");
            if (n.mode == 2 && !(v < (((Key)1) << 32))) throw std::runtime_error("key width");
            int w = IMG_WIDTH[n.mode];
            for (int i2 = 0; i2 < w; ++i2) img[at + i2] = (char)((unsigned)(v >> (8 * i2)) & 255);
            at += w;
        }
    }
    for (size_t r = 0; r < R; ++r)
        wr32(img, hopoff + 4ull * r, hops[r] < 0 ? 0xffffffffull : (unsigned long long)hops[r]);
    return img;
}

// ---------------------------------------------------------------- lookup kernel
struct ImgNode {
    int kind, mode, cached, lo, span, count;
    unsigned long long offset, allocated;
    Key base;
    std::vector<unsigned long long> children;
    std::vector<Key> keys;
};

inline std::vector<ImgNode> decode_image(const std::string& img) {
    if (img.size() < 128 || img.size() % 64) throw std::runtime_error("image size");
    if (memcmp(img.data(), "FIDX", 4) || rd8(img, 4) != 2) throw std::runtime_error("image magic");
    unsigned long long R = rd32(img, 8), N = rd32(img, 12);
    unsigned long long hopoff = rd32(img, 16), total = rd32(img, 20);
    if (R < 1 || R > 64 || N < 1 || N > 2 * R - 1) throw std::runtime_error("image counts");
    if (hopoff % 64 || hopoff <= 64 || hopoff > img.size()) throw std::runtime_error("hop offset");
    if (total != img.size()) throw std::runtime_error("image total");
    std::vector<ImgNode> nodes;
    unsigned long long off = 64;
    for (unsigned long long i = 0; i < N; ++i) {
        if (off + 32 > hopoff) throw std::runtime_error("truncated node");
        ImgNode n;
        n.offset = off;
        n.kind = (int)rd8(img, off + 0);
        n.mode = (int)rd8(img, off + 1);
        n.cached = (int)rd8(img, off + 2);
        n.lo = (int)rd16(img, off + 4);
        n.span = (int)rd16(img, off + 6);
        n.count = (int)rd16(img, off + 8);
        n.allocated = rd32(img, off + 12);
        n.base = rd128(img, off + 16);
        if (n.kind > 1 || n.mode > 2 || n.cached > 1) throw std::runtime_error("node tag");
        if (n.allocated % 64 || !n.allocated) throw std::runtime_error("allocation");
        size_t b = n.kind ? 0 : (size_t)n.count;
        size_t k = n.kind ? (size_t)n.span : (size_t)n.count - 1;
        unsigned long long used = 32ull + 4ull * b + (unsigned long long)k * (unsigned long long)IMG_WIDTH[n.mode];
        if ((used + 63ull) / 64ull * 64ull != n.allocated) throw std::runtime_error("node size");
        unsigned long long at = off + 32;
        for (size_t c = 0; c < b; ++c) { n.children.push_back(rd32(img, at)); at += 4; }
        for (size_t c = 0; c < k; ++c) {
            Key raw = 0;
            int w = IMG_WIDTH[n.mode];
            for (int i2 = w - 1; i2 >= 0; --i2) raw = (raw << 8) | (unsigned)(unsigned char)img[at + i2];
            n.keys.push_back(n.mode ? raw + n.base : raw);
            at += w;
        }
        nodes.push_back(n);
        off += n.allocated;
    }
    if (off != hopoff) throw std::runtime_error("node bytes");
    return nodes;
}

// Search real image bytes; root-to-leaf byte offsets, run index and hop.
inline std::vector<Answer> search_image(const std::string& img, const std::vector<Key>& addrs) {
    std::vector<ImgNode> nodes = decode_image(img);
    unsigned long long hopoff = rd32(img, 16);
    unsigned long long R = rd32(img, 8);
    std::vector<long long> hops((size_t)R);
    for (unsigned long long r = 0; r < R; ++r) {
        unsigned long long v = rd32(img, hopoff + 4ull * r);
        hops[(size_t)r] = (v == 0xffffffffull) ? -1 : (long long)v;
    }
    std::vector<Answer> out;
    for (size_t a = 0; a < addrs.size(); ++a) {
        Key x = addrs[a];
        Answer ans; ans.hop = -1; ans.run = -1;
        unsigned long long cur = 64;
        int guard = 0;
        while (true) {
            if (++guard > 512) throw std::runtime_error("cycle");
            size_t idx = 0; bool found = false;
            for (size_t i = 0; i < nodes.size(); ++i)
                if (nodes[i].offset == cur) { idx = i; found = true; break; }
            if (!found) throw std::runtime_error("missing node");
            const ImgNode& n = nodes[idx];
            ans.path.push_back(cur);
            if (n.kind) {
                size_t c = 0;
                while (c < n.keys.size() && !(x < n.keys[c])) ++c;   // count of keys <= x
                if (c == 0) throw std::runtime_error("leaf predecessor");
                ans.run = n.lo + (int)c - 1;
                break;
            }
            size_t c = 0;
            while (c < n.keys.size() && !(x < n.keys[c])) ++c;
            if (c >= n.children.size()) throw std::runtime_error("child select");
            cur = n.children[c];
        }
        if (ans.run < 0 || (unsigned long long)ans.run >= R) throw std::runtime_error("run range");
        ans.hop = hops[(size_t)ans.run];
        out.push_back(ans);
    }
    return out;
}

inline PackedResult pack_image(const std::vector<Key>& starts, const std::vector<long long>& hops,
                               const std::vector<Layout>& nodes, const std::vector<Key>& addrs) {
    PackedResult r;
    r.image = build_image(starts, hops, nodes);
    r.answers = search_image(r.image, addrs);
    return r;
}

inline std::vector<Answer> trace_image(const std::string& img, const std::vector<Key>& addrs) {
    return search_image(img, addrs);
}
